<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {invoke} from '@tauri-apps/api/core'
import {useI18n} from '@/lib/i18n'
import {localDayBounds} from '@/lib/businessDay'
const {pick,formatDateTime}=useI18n()
type Event={id:string;event_type:string;actor_id:string|null;actor_name:string|null;occurred_at:string;entity_type:string;entity_id:string;reference:string;details:string;historical:number}
type Page={events:Event[];total:number;types:string[];users:Array<{id:string;full_name:string}>}
const result=ref<Page>({events:[],total:0,types:[],users:[]}),from=ref(''),to=ref(''),type=ref(''),user=ref(''),offset=ref(0),busy=ref(false),error=ref('')
const names:Record<string,[string,string]>={catalog_import:['Catalog import','فہرست کی درآمد'],catalog_bulk:['Bulk catalog update','فہرست کی اجتماعی تبدیلی'],controlled_sale:['Controlled sale','کنٹرول شدہ دوا کی فروخت'],adjustment_approved:['Adjustment approved','اسٹاک ترمیم منظور'],adjustment_rejected:['Adjustment rejected','اسٹاک ترمیم مسترد'],return_approved:['Return approved','واپسی منظور'],return_rejected:['Return rejected','واپسی مسترد'],return_refunded:['Return completed','واپسی مکمل'],expense_void:['Expense voided','خرچ منسوخ'],customer_payment:['Customer payment','گاہک کی وصولی'],customer_payment_void:['Customer payment voided','وصولی منسوخ'],credit_sale:['Credit sale','ادھار فروخت'],credit_return:['Return account credit','واپسی کا کھاتہ کریڈٹ'],customer_limit:['Customer credit limit','گاہک کی کریڈٹ حد'],shift_open:['Shift opened','شفٹ کھولی'],shift_close:['Shift closed','شفٹ بند'],supplier_payment:['Supplier payment','سپلائر کو ادائیگی'],quarantine:['Quarantine placed','قرنطینہ رکھا'],quarantine_released:['Quarantine released','قرنطینہ جاری'],quarantine_written_off:['Quarantine written off','قرنطینہ تلف'],quarantine_returned:['Quarantine returned','قرنطینہ سپلائر کو واپس']}
const eventName=(value:string)=>names[value]?pick(...names[value]):value
onMounted(()=>load())
async function load(reset=true){busy.value=true;error.value='';if(reset)offset.value=0;try{result.value=await invoke<Page>('read_audit_log',{request:{start:from.value?localDayBounds(from.value)[0]:null,end:to.value?localDayBounds(to.value)[1]:null,eventType:type.value||null,actorId:user.value||null,offset:offset.value}})}catch(e){error.value=String(e)}finally{busy.value=false}}
function turn(n:number){offset.value+=n*100;void load(false)}
function clear(){from.value='';to.value='';type.value='';user.value='';void load()}
</script>
<template><div class="tool-terminal documents-terminal"><header class="tool-header"><div><h1>{{pick('Audit Log','پڑتال کا ریکارڈ')}}</h1><p>{{pick('Read-only sensitive activity · admin / manager','حساس سرگرمیوں کا صرف مطالعہ · ایڈمن / منیجر')}}</p></div><button :disabled="busy" @click="clear">{{pick('Clear filters','فلٹر صاف کریں')}}</button></header><form class="commercial-filters" @submit.prevent="load()"><label>{{pick('From','سے')}}<input v-model="from" type="date"/></label><label>{{pick('To','تک')}}<input v-model="to" type="date" :min="from"/></label><label>{{pick('Action','کارروائی')}}<select v-model="type"><option value="">{{pick('All actions','تمام کارروائیاں')}}</option><option v-for="t in result.types" :key="t" :value="t">{{eventName(t)}}</option></select></label><label>{{pick('User','صارف')}}<select v-model="user"><option value="">{{pick('All users','تمام صارفین')}}</option><option v-for="u in result.users" :key="u.id" :value="u.id">{{u.full_name}}</option></select></label><button class="bg-primary" :disabled="busy">{{pick('Apply filters','فلٹر لاگو کریں')}}</button></form><p class="commercial-hint">{{pick('New actions are recorded atomically with their transaction. Imported history reflects the last known record only; missing earlier transitions or actors are not reconstructed. Audit entries cannot be edited or deleted through this app.','نئی کارروائیاں اپنی ٹرانزیکشن کے ساتھ درج ہوتی ہیں۔ درآمد شدہ تاریخ صرف آخری معلوم ریکارڈ ہے؛ نامعلوم پرانی تبدیلیاں یا صارف خود سے نہیں بنائے جاتے۔ ایپ میں یہ اندراج بدلے یا حذف نہیں ہوتے۔')}}</p><p v-if="error" role="alert" class="commercial-error">{{error}}</p><div class="commercial-table-scroll"><p v-if="busy" role="status">{{pick('Loading…','لوڈ ہو رہا ہے…')}}</p><table v-else><thead><tr><th>{{pick('When','وقت')}}</th><th>{{pick('Action','کارروائی')}}</th><th>{{pick('User','صارف')}}</th><th>{{pick('Reference','حوالہ')}}</th><th>{{pick('Details','تفصیل')}}</th></tr></thead><tbody><tr v-for="e in result.events" :key="e.id"><td>{{formatDateTime(e.occurred_at)}}<small v-if="e.historical">{{pick('Imported history','درآمد شدہ تاریخ')}}</small></td><td>{{eventName(e.event_type)}}</td><td>{{e.actor_name||pick('Unknown / historical actor','نامعلوم / پرانا صارف')}}<small>{{e.actor_id}}</small></td><td>{{e.reference}}<small>{{e.entity_type}}</small></td><td style="max-width:330px;white-space:normal;overflow-wrap:anywhere">{{e.details}}</td></tr><tr v-if="!result.events.length"><td colspan="5" class="commercial-empty">{{pick('No audit events match these filters.','ان فلٹرز کے مطابق کوئی ریکارڈ نہیں۔')}}</td></tr></tbody></table></div><footer class="tool-summary"><div><small>{{pick('Matching events','ملنے والے اندراج')}}</small><strong>{{result.total}}</strong></div><div><small>{{pick('Page','صفحہ')}}</small><strong>{{Math.floor(offset/100)+1}} / {{Math.max(1,Math.ceil(result.total/100))}}</strong></div><button :disabled="busy||offset===0" @click="turn(-1)">{{pick('Previous','پچھلا')}}</button><button :disabled="busy||offset+100>=result.total" @click="turn(1)">{{pick('Next','اگلا')}}</button></footer></div></template>
